/* =============================================================================
   Proyecto   : Bajo el Capó · DP-800 (Microsoft SQL AI Developer Associate)
   Script     : database/03_insert_data.sql
   Objetivo   : Carga los datos de prueba: 8 marcas, 24 modelos, 228 vehículos,
                57 averías, 207 relaciones modelo-avería, 4 comerciales, 24 clientes,
                44 reservas y 16 ventas. El modelo Dacia Jogger no tiene averías
                registradas (caso de control del RAG).
   Requisitos : 02_create_tables.sql ejecutado sobre una BD recién creada.
                Se ejecuta antes de 05_procedures.sql, así que el trigger de
                reservas todavía no existe: el bloque I fija el estado de los coches.
   Ejecución  : SSMS 22, o
                sqlcmd -S localhost -d BajoElCapoDB -E -C -b -i database\03_insert_data.sql
   Siguiente  : 04_views.sql
   Nota       : Datos ficticios. Los emails usan dominios reservados (example.*).
   Autor      : Emmanuel Grande Sierra
   ============================================================================= */

USE BajoElCapoDB;
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
GO

-- A: protección; el script solo se ejecuta sobre tablas vacías (todo en un lote y una transacción)
IF EXISTS (SELECT 1 FROM catalogo.Marcas)
    THROW 50090, N'La BD ya tiene datos. Ejecuta 01 y 02 antes de este script.', 1;

BEGIN TRANSACTION;

-- B: marcas
INSERT INTO catalogo.Marcas (nombre, pais) VALUES
    (N'Seat', N'España'),
    (N'Volkswagen', N'Alemania'),
    (N'Renault', N'Francia'),
    (N'Peugeot', N'Francia'),
    (N'Toyota', N'Japón'),
    (N'Ford', N'Estados Unidos'),
    (N'Dacia', N'Rumanía'),
    (N'Kia', N'Corea del Sur');

-- C: modelos; la marca se busca por nombre (anio_fin NULL = sigue en producción)
INSERT INTO catalogo.Modelos (marca_id, nombre, segmento, anio_inicio, anio_fin)
SELECT ma.marca_id, v.modelo, v.segmento, v.anio_inicio, v.anio_fin
FROM (VALUES
