    (N'Renault', N'Mégane', N'Compacto', 2016, 2023),
    (N'Renault', N'Scénic', N'Monovolumen', 2016, 2022),
    (N'Peugeot', N'208', N'Utilitario', 2019, NULL),
    (N'Peugeot', N'308 SW', N'Familiar', 2014, 2021),
    (N'Peugeot', N'3008', N'SUV', 2016, NULL),
    (N'Toyota', N'Yaris', N'Utilitario', 2014, 2020),
