JOIN catalogo.Modelos AS mo ON mo.marca_id = ma.marca_id AND mo.nombre = v.modelo;

-- E: catálogo de averías conocidas
INSERT INTO taller.Averias (titulo, sintoma, causa, solucion, coste_estimado) VALUES
    (N'Cadena de distribución estirada (1.4 TSI)',
     N'Ruido metálico de traqueteo durante los primeros segundos tras arrancar en frío.',
     N'El tensor hidráulico pierde presión y la cadena se estira con los kilómetros.',
     N'Sustituir el kit de cadena, tensor y guías, y ajustar la distribución.', 1100.00),
    (N'Embrague de la caja DSG7 con tirones',
     N'Tirones al arrancar y cambios bruscos entre primera y segunda en atascos.',
     N'Desgaste del doble embrague seco de la caja DQ200 por uso urbano intenso.',
     N'Sustituir el doble embrague y recalibrar los puntos de contacto con diagnosis.', 1800.00),
    (N'Mecatrónica de la caja DSG averiada',
     N'El testigo del cambio parpadea y la caja entra en modo de emergencia.',
     N'Fallo en la unidad de control electrohidráulica o fuga en el acumulador de presión.',
     N'Reparar o sustituir la mecatrónica y actualizar el software de la caja.', 1500.00),
    (N'Válvula EGR obstruida (2.0 TDI)',
     N'Pérdida de potencia, humo negro al acelerar y testigo de motor encendido.',
     N'Acumulación de carbonilla en la válvula por trayectos cortos y uso urbano.',
     N'Limpiar o sustituir la válvula EGR y borrar los códigos de avería.', 450.00),
    (N'Filtro de partículas colmatado',
     N'Testigo del filtro de partículas encendido y el motor entra en modo protegido.',
     N'Trayectos cortos que no permiten completar la regeneración automática del filtro.',
     N'Hacer una regeneración forzada con diagnosis o limpiar el filtro.', 600.00),
    (N'Bomba de agua con fuga (1.4 TSI)',
     N'Pérdida de refrigerante y aguja de temperatura más alta de lo normal.',
     N'La carcasa de plástico de la bomba se agrieta con los ciclos de calor.',
     N'Sustituir la bomba de agua y el termostato, y purgar el circuito.', 520.00),
    (N'Bobina de encendido defectuosa',
     N'Tirones al acelerar, motor que vibra al ralentí y testigo de motor.',
     N'Una bobina se deteriora por el calor del motor y deja de dar chispa.',
     N'Sustituir la bobina afectada y revisar las bujías.', 180.00),
    (N'Sensor de presión diferencial del filtro de partículas',
     N'Testigo de motor y el filtro de partículas no llega a regenerarse.',
     N'El sensor o sus manguitos se dañan y envían lecturas erróneas.',
     N'Sustituir el sensor y comprobar los manguitos de presión.', 150.00),
    (N'Pantalla multimedia bloqueada',
     N'La pantalla central se congela o el sistema se reinicia durante la marcha.',
     N'Errores del software del sistema de infoentretenimiento.',
     N'Actualizar el software y, si persiste, sustituir la unidad.', 120.00),
    (N'Bomba de alta presión de inyección (1.5 dCi)',
     N'Dificultad para arrancar, tirones y pérdida de potencia.',
     N'Desgaste interno de la bomba por combustible de mala calidad o agua en el gasóleo.',
     N'Sustituir la bomba de alta presión y el filtro de combustible, y limpiar el circuito.', 1300.00),
    (N'Cojinetes de biela desgastados (1.5 dCi)',
     N'Ruido metálico grave del motor que aumenta al acelerar.',
     N'Lubricación deficiente por alargar los intervalos de cambio de aceite.',
     N'Reparar el motor sustituyendo los cojinetes; en casos graves, cambiar el motor.', 2800.00),
    (N'Freno de estacionamiento eléctrico bloqueado',
     N'Mensaje de avería del freno de mano y el freno no se suelta o no se activa.',
     N'Fallo del motor eléctrico de la pinza o de la centralita del freno.',
     N'Sustituir el motor del freno de estacionamiento y calibrarlo con diagnosis.', 600.00),
    (N'Navegador R-Link sin respuesta',
     N'El navegador y la radio no responden y la pantalla queda en negro.',
     N'Fallo del software del sistema R-Link.',
     N'Actualizar el software o sustituir la unidad multimedia.', 350.00),
    (N'Tarjeta manos libres no detectada',
     N'El coche no detecta la tarjeta y no permite arrancar.',
     N'Pila de la tarjeta agotada o fallo del lector del habitáculo.',
     N'Sustituir la pila de la tarjeta o el lector y reprogramar la tarjeta.', 220.00),
    (N'Electroválvula del sistema GLP sucia',
     N'El coche no cambia a GLP o lo hace con tirones.',
     N'Suciedad en la electroválvula y el filtro de fase gaseosa.',
     N'Limpiar la electroválvula y sustituir los filtros del sistema de GLP.', 250.00),
    (N'Correa de distribución en baño de aceite degradada (1.2 PureTech)',
     N'Testigo de presión de aceite, pérdida de potencia y ruido del motor.',
     N'La correa húmeda se degrada, suelta partículas y obstruye la bomba de aceite.',
     N'Sustituir correa, tensor y bomba de vacío, limpiar el cárter y cambiar el aceite.', 1800.00),
    (N'Consumo excesivo de aceite (1.2 PureTech)',
     N'El nivel de aceite baja mucho entre revisiones y aparece humo azulado.',
     N'Segmentos de pistón pegados por la carbonilla.',
     N'Descarbonizar o sustituir los segmentos; en casos graves, reparar el motor.', 2500.00),
    (N'Depósito de AdBlue averiado',
     N'Aviso de que el motor no arrancará en un número de kilómetros.',
     N'Fallo de la bomba o del sensor de nivel del depósito de AdBlue.',
     N'Sustituir el conjunto del depósito o la bomba de AdBlue.', 900.00),
    (N'Actuador del turbo bloqueado',
     N'Pérdida de potencia repentina y modo protegido del motor.',
     N'El actuador electrónico de la geometría variable se agarrota.',
     N'Limpiar o sustituir el actuador del turbo y calibrarlo.', 700.00),
    (N'Caja automática EAT6 con golpes',
     N'Golpes al cambiar de marcha, sobre todo en frío.',
     N'Aceite de la caja degradado y adaptaciones desajustadas.',
     N'Cambiar el aceite de la caja y reiniciar las adaptaciones.', 450.00),
    (N'Batería de tracción con autonomía reducida',
     N'La autonomía real baja claramente respecto a la homologada.',
