-- K: estado de cada coche según sus reservas (lo que hará el trigger tr_reservas_estado a partir de 05)
UPDATE ve
SET estado = CASE
        WHEN EXISTS (SELECT 1 FROM ventas.Reservas AS r WHERE r.vehiculo_id = ve.vehiculo_id AND r.estado = N'Vendida') THEN N'Vendido'
        WHEN EXISTS (SELECT 1 FROM ventas.Reservas AS r WHERE r.vehiculo_id = ve.vehiculo_id AND r.estado = N'Activa')  THEN N'Reservado'
        ELSE N'Disponible'
    END
FROM catalogo.Vehiculos AS ve;

