GO

-- L: recuentos por tabla para comprobar la carga
SELECT N'Marcas' AS tabla, COUNT(*) AS filas FROM catalogo.Marcas
UNION ALL SELECT N'Modelos', COUNT(*) FROM catalogo.Modelos
UNION ALL SELECT N'Vehiculos', COUNT(*) FROM catalogo.Vehiculos
UNION ALL SELECT N'Averias', COUNT(*) FROM taller.Averias
UNION ALL SELECT N'ModeloAveria', COUNT(*) FROM taller.ModeloAveria
UNION ALL SELECT N'Comerciales', COUNT(*) FROM ventas.Comerciales
UNION ALL SELECT N'Clientes', COUNT(*) FROM ventas.Clientes
UNION ALL SELECT N'Reservas', COUNT(*) FROM ventas.Reservas
UNION ALL SELECT N'Ventas', COUNT(*) FROM ventas.Ventas;

SELECT estado, COUNT(*) AS coches FROM catalogo.Vehiculos GROUP BY estado;
GO

